(function () {
  var FRAME_MS = 30; // orijinal GIF ile ayni hiz
  var el = document.getElementById("xrdd-ascii");
  if (!el) return;

  var still = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  el.textContent = FRAMES[0];
  if (still) return; // hareketi kapatan kullanicilara sabit kare

  var i = 0, last = performance.now(), acc = 0;
  function tick(now) {
    acc += now - last;
    last = now;
    if (acc >= FRAME_MS) {
      var step = Math.floor(acc / FRAME_MS);
      acc -= step * FRAME_MS;
      i = (i + step) % FRAMES.length;
      el.textContent = FRAMES[i];
    }
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
})();
